  FUNCTION ONUMM5N10_MATMUL_ONUMM5N10(LHS,RHS)&
    RESULT(RES)
    IMPLICIT NONE
    TYPE(ONUMM5N10), INTENT(IN) :: LHS(:,:) 
    TYPE(ONUMM5N10), INTENT(IN) :: RHS(:,:) 
    TYPE(ONUMM5N10) :: TMP 
    TYPE(ONUMM5N10) :: RES(SIZE(LHS,1),SIZE(RHS,2)) 
    INTEGER :: I,J,K 

    ! Dimension check
    IF (SIZE(LHS,2) /= SIZE(RHS,1)) THEN
      STOP "Runtime error: " // &
           "Dimension mismatch in MATMUL."
    END IF
    DO I = 1, SIZE(LHS,1)
      DO J = 1, SIZE(RHS,2)
        TMP = 0.0_DP
        DO K = 1, SIZE(LHS,2)
          TMP = TMP + LHS( I, K )*RHS( K, J )
        END DO
        RES( I, J ) = TMP
      END DO
    END DO

  END FUNCTION ONUMM5N10_MATMUL_ONUMM5N10

